solution.solution.cpp:
#include <string>
#include <vector>

constexpr unsigned LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR = 0x100;
constexpr unsigned LOAD_LIBRARY_SEARCH_APPLICATION_DIR = 0x200;
constexpr unsigned LOAD_LIBRARY_SEARCH_USER_DIRS = 0x400;
constexpr unsigned LOAD_LIBRARY_SEARCH_SYSTEM32 = 0x800;
constexpr unsigned LOAD_LIBRARY_SEARCH_DEFAULT_DIRS = 0x1000;

std::vector<std::string> searchedFolders(unsigned flags, const std::string& appDir, const std::string& dllDir, const std::vector<std::string>& userDirs)
{
    if (flags & LOAD_LIBRARY_SEARCH_DEFAULT_DIRS) flags |= LOAD_LIBRARY_SEARCH_APPLICATION_DIR | LOAD_LIBRARY_SEARCH_USER_DIRS | LOAD_LIBRARY_SEARCH_SYSTEM32;
    std::vector<std::string> out;
    if (flags & LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR) out.push_back(dllDir);
    if (flags & LOAD_LIBRARY_SEARCH_APPLICATION_DIR) out.push_back(appDir);
    if (flags & LOAD_LIBRARY_SEARCH_USER_DIRS) out.insert(out.end(), userDirs.begin(), userDirs.end());
    if (flags & LOAD_LIBRARY_SEARCH_SYSTEM32) out.push_back("C:\\Windows\\System32");
    return out;
}

unitTests:
using Dirs = std::vector<std::string>;
TEST("default dirs") { CHECK_EQ(searchedFolders(LOAD_LIBRARY_SEARCH_DEFAULT_DIRS, "C:\\App", "C:\\App\\plugins\\fog", { "D:\\Shared" }), (Dirs{ "C:\\App", "D:\\Shared", "C:\\Windows\\System32" })); }
TEST("plugin with its own folder") { CHECK_EQ(searchedFolders(LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR | LOAD_LIBRARY_SEARCH_DEFAULT_DIRS, "C:\\App", "C:\\App\\plugins\\fog", {}), (Dirs{ "C:\\App\\plugins\\fog", "C:\\App", "C:\\Windows\\System32" })); }
TEST("only System32") { CHECK_EQ(searchedFolders(LOAD_LIBRARY_SEARCH_SYSTEM32, "C:\\App", "x", { "y" }), (Dirs{ "C:\\Windows\\System32" })); }
TEST("no flags") { CHECK(searchedFolders(0, "C:\\App", "x", { "y" }).empty()); }

